#!/usr/bin/env python3
"""Create additive observed-runtime receipt without changing the prepared freeze."""
from pathlib import Path
import datetime, gzip, sys
import collect as c
import verify_runtime

assert not (c.HERE / 'runtime-receipt.json').exists()
replay = verify_runtime.verify()
stamp = datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')
attempt = c.HERE / 'runtime-proof-attempts' / stamp
for script in c.HERE.glob('*.py'):
    c.save(attempt / 'scripts' / script.name, script.read_bytes())
c.save(attempt / 'stdout.log.gz', gzip.compress(c.enc(replay), mtime=0))
c.save(attempt / 'stderr.log.gz', gzip.compress(b'', mtime=0))
c.save(attempt / 'command.json', {'argv': [sys.executable, '-B', str(c.HERE / 'finalize_runtime.py')], 'readOnlyReplayFunction': 'verify_runtime.verify', 'cwd': str(c.ROOT), 'pythonVersion': sys.version, 'pythonExecutableSHA256': c.sha(Path(sys.executable).read_bytes()), 'sourceClosure': replay['candidateClosure'], 'exitCode': 0, 'runtimeOrCompilerRerun': False})
c.save(c.HERE / 'runtime-read-only-replay.json', replay)
results = c.read_json(c.HERE / 'runtime-results.json')
rows = replay['observedRows']
focused = [x for x in rows if x['family'] == 'focused']
receipt = {'schema': 'mixer.swift-lifecycle.runtime-v3-observed-receipt.1', 'observedUTC': datetime.datetime.now(datetime.timezone.utc).isoformat(), 'sourceRevisionContext': c.read_json(c.HERE / 'finite-representation-selection.json')['sourceRevisionContext'], 'candidateClosure': replay['candidateClosure'], 'preRuntimeFreezeSHA256': c.sha((c.HERE / 'pre-runtime-freeze.json').read_bytes()), 'preRuntimeSealSHA256': c.sha((c.HERE / 'seal.json').read_bytes()), 'preRuntimeFrozenFilesPreserved': 357, 'rootRuntimeSelectionSHA256': verify_runtime.SELECTION_SHA, 'rootCommand': ['python3', '-B', 'verification/swift-reactor-lifecycle-runtime-v3/run_runtime.py', '--representation-selection', '/Users/andreyyurlov/Documents/dev/mixer/verification/swift-reactor-lifecycle-runtime-v3-root-review/runtime-selection.json', '--selection-sha256', verify_runtime.SELECTION_SHA], 'selectedMatrixComplete': replay['selectedMatrixComplete'], 'allObservedRowsPassed': replay['allObservedRowsPassed'], 'plannedRows': replay['plannedRows'], 'completedRows': replay['completedRows'], 'focusedContexts': len(focused), 'focusedLifecycleIdentityExecutions': sum(x['tests'] for x in focused), 'focusedLifecycleIdentitiesPassed': sum(x['identitiesPassed'] for x in focused), 'observedTotals': replay['totals'], 'observedRows': rows, 'runtimeFailures': [x for x in results if not x['passed']], 'unchangedFailedTestReruns': 0, 'noSourceChangeAfterCompilerProofOrDuringRuntime': True, 'environmentScope': 'macOS aarch64 Rust host unit/integration tests with authored synthetic fixtures and qualified Node oracle; no simulator, emulator or physical-device receipt', 'SL13Observed': 'All focused contexts passed selected cache-ticket deltas+1,+2,+0 and live-entry sequence0,1,3,3, retained cumulative work/hit/resident/budget checks, original deadline and actual consuming retire.', 'SL09Observed': 'All focused contexts passed the preserved constructor/initializer exact failure diagnostics and consuming cleanup checks; remaining original edge permutations stay pending.', 'originalLimits': c.read_json(c.HERE / 'receipt.json')['originalLimits'], 'additionalAccountingCredit': 0, 'allRuntimeExecutablesOutputsCommandsToolVersionsRetained': True, 'exactCompilerSysrootAndQualifiedNodePinsCheckedBeforeEachCommand': True, 'fullAppleLoaderAndDyldCacheQualificationChecksBeforeNodeOracle': replay['totals'].get('qualifiedNodeOracleRows', 0), 'originalCoverageLedger': c.read_json(c.HERE / 'authored-coverage.json'), 'originalCoverageLedgerSHA256': c.sha((c.HERE / 'authored-coverage.json').read_bytes()), 'originalPlannedMatrixSHA256': c.sha((c.HERE / 'planned-matrix-unchanged.json').read_bytes()), 'fullPlannedSLRowsComplete': False, 'fullMatrixRemainingFailureCheckpointBudgetWASIVariants': 'pending', 'SL12GuestTableMutation': 'unsupported/unimplemented/unrun', 'realFull53MBReactor': 'pending/unread/unhashed/unrun', 'physicalPhones': 'disconnected-deferred', 'immutablePublishedSeparateRepositoryFieldLogRelease': 'pending', 'D3G07G08DogfoodStoreCustomerOperationalGA': 'pending', 'rootRuntimeAcceptancePending': True, 'allOwnedRuntimeTargetsCleaned': True, 'nativeInstancesCreated': 0, 'liveVMModified': False, 'gitUsed': False, 'networkUsed': False, 'sharedTrackerModified': False, 'preparedReceiptAndDocumentRemainImmutableHistoricalEvidence': True, 'preparedReceiptSHA256': c.sha((c.HERE / 'receipt.json').read_bytes()), 'preparedDocumentSHA256': c.sha((c.ROOT / 'docs/swift-reactor-lifecycle-runtime-v3.md').read_bytes()), 'readOnlyReplaySHA256': c.sha(c.enc(replay))}
c.save(c.HERE / 'runtime-receipt.json', receipt)
print(c.enc({'receipt': 'runtime-receipt.json', 'schema': receipt['schema'], 'selectedMatrixComplete': receipt['selectedMatrixComplete'], 'completedRows': receipt['completedRows'], 'focusedLifecycleIdentitiesPassed': receipt['focusedLifecycleIdentitiesPassed'], 'observedTotals': receipt['observedTotals'], 'rootRuntimeAcceptancePending': True, 'fullPlannedSLRowsComplete': False}).decode())
